ALTER TABLE carts ADD COLUMN expires_at TIMESTAMP(3) NOT NULL DEFAULT (CURRENT_TIMESTAMP + interval '30 days'), ADD COLUMN coupon_code VARCHAR(40), ADD COLUMN coins_enabled BOOLEAN NOT NULL DEFAULT false;
UPDATE carts SET expires_at = created_at + interval '30 days';
ALTER TABLE cart_items ADD COLUMN saved_for_later BOOLEAN NOT NULL DEFAULT false, ADD COLUMN last_price_paise INTEGER;
CREATE TABLE coupons (code VARCHAR(40) PRIMARY KEY, discount_bps INTEGER NOT NULL CHECK (discount_bps BETWEEN 1 AND 10000), min_total_paise INTEGER NOT NULL DEFAULT 0 CHECK (min_total_paise >= 0), max_discount_paise INTEGER CHECK (max_discount_paise >= 0), starts_at TIMESTAMP(3) NOT NULL, ends_at TIMESTAMP(3) NOT NULL, active BOOLEAN NOT NULL DEFAULT true);
ALTER TABLE products ADD COLUMN gst_rate_bps INTEGER CHECK (gst_rate_bps BETWEEN 0 AND 10000);
ALTER TABLE vendors ADD COLUMN standard_delivery_paise INTEGER NOT NULL DEFAULT 0 CHECK (standard_delivery_paise >= 0), ADD COLUMN express_delivery_paise INTEGER CHECK (express_delivery_paise >= 0), ADD COLUMN same_day_delivery_paise INTEGER CHECK (same_day_delivery_paise >= 0), ADD COLUMN delivery_gst_rate_bps INTEGER CHECK (delivery_gst_rate_bps BETWEEN 0 AND 10000);
ALTER TABLE orders ADD COLUMN checkout_key UUID UNIQUE, ADD COLUMN checkout_fingerprint TEXT, ADD COLUMN reservation_expires_at TIMESTAMP(3), ADD COLUMN reservation_state VARCHAR(20), ADD COLUMN razorpay_order_id TEXT UNIQUE, ADD COLUMN razorpay_payment_id TEXT UNIQUE, ADD COLUMN gateway_creating BOOLEAN NOT NULL DEFAULT false, ADD COLUMN confirmed_at TIMESTAMP(3), ADD COLUMN escrow_status TEXT, ADD COLUMN coins_used INTEGER NOT NULL DEFAULT 0, ADD COLUMN wallet_used_paise INTEGER NOT NULL DEFAULT 0, ADD COLUMN gstin VARCHAR(15), ADD COLUMN tax_breakup JSONB, ADD COLUMN checkout_payment_method TEXT;
CREATE INDEX orders_reservation_state_reservation_expires_at_idx ON orders(reservation_state, reservation_expires_at);
